using System;
using Framework.Parameters;

namespace Framework.AI.Core
{
    /// <summary>
    /// エージェントの各機能が共有する基本情報を保持する。
    /// </summary>
    /// <typeparam name="TParameter">
    /// パラメーターを識別する型。
    /// </typeparam>
    /// <remarks>
    /// パラメーター集合の所有権は生成元が保持する。
    /// Contextはパラメーター集合を破棄しない。
    /// </remarks>
    public sealed class AgentContext<TParameter>
    {
        /// <summary>
        /// エージェント固有の識別子を取得する。
        /// </summary>
        public Guid Id { get; }

        /// <summary>
        /// エージェントの表示名を取得する。
        /// </summary>
        public string Name { get; }

        /// <summary>
        /// 個体固有のパラメーター集合を取得する。
        /// </summary>
        public ParameterSet<TParameter> Parameters { get; }

        /// <summary>
        /// 新しい識別子を使用して共有情報を生成する。
        /// </summary>
        /// <param name="name">エージェントの表示名</param>
        /// <param name="parameters">個体固有のパラメーター集合</param>
        public AgentContext(
            string name,
            ParameterSet<TParameter> parameters)
            : this(Guid.NewGuid(), name, parameters)
        {
        }

        /// <summary>
        /// 指定された識別子を使用して共有情報を生成する。
        /// </summary>
        /// <param name="id">エージェント固有の識別子</param>
        /// <param name="name">エージェントの表示名</param>
        /// <param name="parameters">個体固有のパラメーター集合</param>
        /// <exception cref="ArgumentException">
        /// 識別子または表示名が不正な場合に発生する。
        /// </exception>
        /// <exception cref="ArgumentNullException">
        /// パラメーター集合がnullの場合に発生する。
        /// </exception>
        /// <exception cref="ObjectDisposedException">
        /// パラメーター集合が破棄済みの場合に発生する。
        /// </exception>
        public AgentContext(
            Guid id,
            string name,
            ParameterSet<TParameter> parameters)
        {
            if (id == Guid.Empty)
            {
                throw new ArgumentException(
                    "空の識別子は使用できません。",
                    nameof(id));
            }

            if (string.IsNullOrWhiteSpace(name))
            {
                throw new ArgumentException(
                    "表示名を指定してください。",
                    nameof(name));
            }

            if (parameters == null)
            {
                throw new ArgumentNullException(
                    nameof(parameters));
            }

            if (parameters.IsDisposed)
            {
                throw new ObjectDisposedException(
                    nameof(parameters));
            }

            Id = id;
            Name = name;
            Parameters = parameters;
        }
    }
}
